export const STRINGS = { en, de, nl, fr };
export function strings(lang, source) {
  const base = STRINGS[lang] || en;
  if (source !== 'garmin') return base;
  const g = GARMIN[lang] || GARMIN.en;
  return Object.assign({}, base, g, { cards: Object.assign({}, base.cards, g.cards || {}) });
}
export function fill(s, v = {}) { return String(s).replace(/\{(\w+)\}/g, (m, k) => (v[k] === undefined ? m : v[k])); }
